# Configuration for AWS Transcribe

To use this STT service in bot.py, replace the STT initialization with:

from pipecat.services.aws.stt import AWSTranscribeSTTService

stt = AWSTranscribeSTTService(
    api_key=os.getenv("API_KEY"),  # Use appropriate env var
    **{
    "region": "us-east-1"
}
)
